"""Site-specific legal information. Never invent an operator identity or address.
Brand-only copy is not represented as a complete Article 10 KVKK notice.
Reviewed against public primary sources on 2026-10-27; scope is the current demo.
"""
from html import escape

def legal_document(sections,related):
 toc='<nav class="legal-toc" aria-label="Sayfa içeriği"><b>Bu sayfada</b>'+''.join(f'<a href="#{key}">{title}</a>' for key,title,body in sections)+f'<a class="legal-related" href="/{related[0]}/">{related[1]} ↗</a></nav>'
 prose='<article class="legal-prose"><p class="legal-version">Son güncelleme: <time datetime="2026-10-27">27 Ekim 2026</time></p>'+''.join(f'<section id="{key}"><h2>{title}</h2>{body}</section>' for key,title,body in sections)+'</article>'
 return '<div class="legal-layout">'+toc+prose+'</div>'

privacy=[
 ('kapsam','1. Kapsam ve iletişim',paras(
  'Bu politika, <strong>Veri Burada</strong> markasıyla sunulan www.veriburada.com tanıtım sitesi, sitedeki örnek arama deneyimi ve iletişim alanı için hazırlanmıştır. “Site” ifadesi bu kapsamı belirtir; Veri Burada bir marka adı olarak kullanılmaktadır.',
  'Mevcut deneyimde hesap açılmaz, kart bilgisi alınmaz ve ödeme yapılmaz. Örnek arama gerçek işletme verisi toplamaz. Ayrı bir uygulamada sunulacak üyelik, ödeme veya gerçek arama hizmetlerinin veri kullanımı bu metnin kapsamında değildir.',
  'Gizlilik ve veri kullanımı hakkında iletişim için belirtilen adres: <a href="mailto:destek@veriburada.com">destek@veriburada.com</a>. Sitedeki iletişim alanının nasıl çalıştığı aşağıda ayrıca açıklanmıştır.')),
 ('veriler','2. Hangi bilgiler işlenir?',
  '<div class="legal-table-scroll" role="region" tabindex="0" aria-label="Bilgi türleri ve kullanım amaçları"><table class="legal-data-table"><thead><tr><th scope="col">Bilgi</th><th scope="col">Kullanım amacı</th><th scope="col">Nasıl elde edilir?</th></tr></thead><tbody>'+
  ''.join(f'<tr><th scope="row">{name}</th><td>{purpose}</td><td>{method}</td></tr>' for name,purpose,method in [
   ('Arama tercihleri','Seçtiğiniz bölge ve işletme türüne uygun örnek önizlemeyi hazırlamak; adımlar arasındaki seçimleri korumak.','İşaretlediğiniz kullanım amacı ve bilgi alanları; seçtiğiniz veya yazdığınız işletme türü, il ve ilçe.'),
   ('Teknik erişim bilgileri','Sayfaları sunmak, istekleri karşılamak, hataları incelemek ve altyapı güvenliğini sağlamak.','Bağlantı sırasında barındırma altyapısına iletilen IP adresi, tarayıcı/istemci bilgileri, istek adresi ve zamanı gibi teknik bilgiler.'),
   ('Gönderdiğiniz iletişim içeriği','Göndermeyi seçtiğiniz talebi değerlendirmek ve yanıtlamak.','E-posta uygulamanızdan gerçekten gönderdiğiniz konu, mesaj, gönderici adresi ve varsa ekler. Formu yazmak tek başına gönderim değildir.')])+
  '</tbody></table></div>'+paras('Arama alanlarına şifre, kimlik numarası, ödeme bilgisi, sağlık bilgisi veya üçüncü kişilerin özel bilgilerini yazmayın. Arama yapmak için bu bilgiler istenmez.')),
 ('yontem','3. İşleme yöntemi ve amaçla sınırlılık',paras(
  'Arama tercihleri, örnek aramayı başlattığınızda sitenin arama işlevine elektronik olarak iletilir. Mevcut örnek modda yanıt, sunucuda oluşturulan temsili kayıtlardan hazırlanır; arama tercihlerinizle Google Haritalar’a canlı sorgu gönderilmez. Bu önizlemede, tercihlerinizi bir müşteri hesabına kaydeden veya kalıcı bir arama geçmişi oluşturan sistem bulunmaz.',
  'Sayfanın çalışması için gereken tarayıcı kaydı ile barındırma altyapısının teknik erişim kayıtları farklıdır. Teknik erişim kayıtları, arama tercihlerinizin bir müşteri hesabına kaydedildiği anlamına gelmez.',
  'Bir bilginin kişisel veri niteliğinde olması hâlinde işleme için 6698 sayılı Kişisel Verilerin Korunması Kanunu’nda öngörülen bir şart bulunması gerekir. Siteyi sunma ve güvenlik amaçları bakımından, temel hak ve özgürlüklere zarar vermeme koşuluyla meşru menfaat; bir hakkın tesisi, kullanılması veya korunması bakımından ilgili kanuni işleme şartı değerlendirilir. Sadece bu sayfayı ziyaret etmeniz, bütün veri işleme faaliyetlerine açık rıza verdiğiniz anlamına gelmez.')),
 ('tarayici','4. Tarayıcıda saklanan tercihler',paras(
  'Arama adımlarındaki seçimleriniz, tarayıcının <strong>sessionStorage</strong> alanında <code>vb-search-draft</code> anahtarıyla tutulur. Kayıt; kullanım amacı, işletme türü, il, ilçe, seçilen bilgi alanları ve bulunduğunuz adımı içerir. Şifre, ödeme bilgisi veya gerçek arama sonucu bu kayda eklenmez.',
  'Bu mekanizma bir HTTP çerezi değildir; tarayıcı tarafından her isteğe otomatik olarak eklenmez. Kayıt genellikle ilgili sekmenin oturumu boyunca kalır. Tarayıcının sekme veya oturum geri yükleme özelliği bu süreyi etkileyebilir. Tercihleri aşağıdaki düğmeyle veya tarayıcınızın site verileri ayarlarından silebilirsiniz.')+
  '<div class="legal-preference-control"><button type="button" class="button secondary" data-clear-search-preferences>Arama tercihlerimi sil</button><p role="status" data-preference-status>Bu işlem yalnızca bu tarayıcıdaki arama taslağını temizler.</p></div>'+paras(
  'Mevcut site kodunda reklam çerezi, yeniden hedefleme pikseli veya üçüncü taraf ziyaretçi analitiği entegrasyonu bulunmaz. Yazı tipleri, tanıtım görselleri ve animasyonlar site dosyalarından yüklenir. Tarayıcıda tutulan arama tercihleri reklam profili oluşturmak için kullanılmaz.')),
 ('ornekler','5. Örnek kayıtlar ve indirilen dosyalar',paras(
  'Animasyonlar, örnek arama sonuçları ve örnek CSV dosyalarındaki işletme bilgileri temsili içeriktir. <code>.example</code> uzantılı alan adları ve sıfırlarla oluşturulmuş örnek telefonlar gerçek iletişim bilgisi olarak kullanılmamalıdır. Bu örneklerde görünen puanlar veya fotoğraflar, gerçek müşteri yorumu ya da referansı değildir.',
  'Örnek CSV indirmesi tarayıcınızda bir dosya oluşturur. Bu işlem, bilgisayarınızdaki diğer dosyaların okunmasını veya sunucuya yüklenmesini gerektirmez. Örnek harita çizimleri, tarayıcınızın hassas konumuna erişildiği anlamına gelmez; mevcut deneyim konum izni istemez.')),
 ('iletisim','6. İletişim formu ve e-posta',paras(
  'İletişim alanı bir sunucu üzerinden mesaj göndermez. Düğmeye bastığınızda yazdığınız konu ve mesaj, <code>mailto:</code> bağlantısıyla cihazınızdaki e-posta uygulamasına aktarılır. Gönderme kararını e-posta uygulamanızda siz verirsiniz; site mesajınızın teslim edildiğini doğrulamaz.',
  'Mesajı gönderirseniz gönderici adresiniz, mesajınız ve varsa ekler e-posta hizmetiniz üzerinden alıcıya iletilir. İlgili e-posta hizmetlerinin veri işleme koşulları ayrıca uygulanır. Göndermediğiniz taslak, bu form tarafından bir destek veritabanına kaydedilmez.')),
 ('altyapi','7. Alıcılar, barındırma ve yurt dışı işlemler',paras(
  'Site, Vercel barındırma ve sunucusuz işlev altyapısına göre hazırlanmıştır. Yayın ortamında sayfa ve isteklerin sunulması sırasında teknik erişim bilgileri barındırma, içerik dağıtımı ve güvenlik hizmeti sağlayıcılarınca işlenebilir. Destek e-postası gönderirseniz e-posta hizmeti sağlayıcıları da iletim sürecinde yer alır.',
  'Vercel’in veri işleme açıklaması, hizmet kapsamında ABD ve diğer ülkelerde işlem yapılabileceğini belirtir. Bu nedenle bütün verilerin yalnızca Türkiye’de işlendiği veya hiç yurt dışına aktarılmadığı yönünde bir taahhüt verilmez. Yurt dışına kişisel veri aktarımı için KVKK’nın 9. maddesindeki şartlar ayrıca sağlanmalıdır; bir sağlayıcının kendi sözleşmesi veya bu sayfanın yayımlanması, tek başına bütün aktarım şartlarının yerine getirildiği anlamına gelmez.',
  'Bu önizlemeye gerçek arama hizmeti bağlı değildir. Bir uygulama veya haricî arama hizmeti bağlanmadan önce, bu hizmetin alıcıları ve veri akışı ayrıca açıklanmalıdır.')),
 ('saklama','8. Saklama, silme ve güvenlik',paras(
  'Arama taslağının tarayıcıdaki saklanması yukarıda açıklanmıştır. Mevcut örnek arama işlevi, sorguları kalıcı bir müşteri hesabında saklamaz. Buna karşılık barındırma hizmetinin teknik kayıtları kendi saklama kuralları ve etkin güvenlik ayarları çerçevesinde tutulabilir; teknik kayıtların saklama süresi kullanılan hizmetin planına ve kayıt ayarlarına bağlıdır.',
  'Gerçekten gönderilen destek yazışmaları, talebin değerlendirilmesi ve varsa hukuki yükümlülükler ya da hakların korunması için gereken süreyle sınırlı tutulmalıdır. Saklama sebebi ortadan kalkan kişisel veriler için uygulanabilir silme, yok etme veya anonimleştirme yükümlülükleri saklıdır.',
  'Hiçbir internet sistemi için mutlak güvenlik garantisi verilemez. Bu nedenle özellikle şifre, ödeme bilgisi ve gereksiz hassas verileri iletişim alanına veya arama kutularına eklemeyin.')),
 ('haklar','9. Kişisel verilerinizle ilgili haklarınız',paras(
  'KVKK kapsamına giren işleme faaliyetlerinde; kişisel verinizin işlenip işlenmediğini öğrenme, işlenmişse bilgi isteme, amacını ve amaçla uyumunu sorgulama, yurt içi ve yurt dışındaki alıcıları öğrenme haklarınız bulunur. Eksik veya yanlış verilerin düzeltilmesini; kanuni şartları oluştuğunda silme ya da yok etmeyi ve bu işlemlerin alıcılara bildirilmesini talep edebilirsiniz. Yalnızca otomatik analiz nedeniyle aleyhinize ortaya çıkan sonuca itiraz edebilir, hukuka aykırı işleme nedeniyle oluşan zararınız için giderim isteyebilirsiniz.',
  'Resmî başvuruların KVKK’nın 13. maddesi ve Veri Sorumlusuna Başvuru Usul ve Esasları Hakkında Tebliğ’deki yöntem ve şartları karşılaması gerekir. Sitedeki e-posta taslağı aracı, başvurunun yapıldığına veya alındığına ilişkin kayıt oluşturan bir KVKK başvuru sistemi değildir. Kanuna uygun başvurular bakımından yanıt süresi, talebin niteliğine göre en kısa süre ve her hâlde en geç otuz gündür.')),
 ('degisiklik','10. Güncellemeler ve ilgili belgeler',paras(
  'Sitenin fiilî veri akışı değiştiğinde bu metin, değişen işleme faaliyetine göre güncellenmelidir. Örneğin gerçek arama, üyelik, ödeme veya ziyaretçi analitiği eklenmesi farklı veri kategorileri ve alıcılar doğurabilir. Güncel metnin tarihi sayfanın başında gösterilir.',
  '<a href="/kullanim-kosullari/">Kullanım koşullarını inceleyin</a>. Mevzuat açıklamaları için <a href="https://www.kvkk.gov.tr/Icerik/6765/AYDINLATMA-YUKUMLULUGUNUN-YERINE-GETIRILMESI-HAKKINDA-KAMUOYU-DUYURUSU" rel="noopener noreferrer" target="_blank">KVKK’nın aydınlatma yükümlülüğü açıklaması</a>, <a href="https://www.kvkk.gov.tr/Icerik/2053/Yurtdisina-Aktarim" rel="noopener noreferrer" target="_blank">yurt dışına aktarım açıklaması</a> ve <a href="https://www.kvkk.gov.tr/Icerik/6938/Kurumumuza-Yapilan-Sikayetlerin-Usul-Sartlarina-Iliskin-Kamuoyu-Duyurusu" rel="noopener noreferrer" target="_blank">başvuru usulü açıklaması</a> başvurulabilecek resmî kaynaklardır.'))
]

terms=[
 ('kapsam','1. Sitenin kapsamı',paras(
  'Bu koşullar, <strong>Veri Burada</strong> markasıyla sunulan www.veriburada.com tanıtım sitesinin ve sitedeki ücretsiz örnek deneyimin kullanımını açıklar. Site; ürünün nasıl çalışacağını tanıtmak, örnek işletme kayıtlarını göstermek ve örnek CSV çıktısını inceletmek amacıyla hazırlanmıştır.',
  'Mevcut önizlemede gerçek işletme araması, hesap oluşturma veya ödeme yapılmaz. Bu sayfa ücretli bir uygulama üyeliğinin, mesafeli satışın veya ödeme işleminin sözleşmesi yerine geçmez. Gelecekte sunulacak uygulama hizmetlerinin kapsamı ve koşulları ilgili işlemden önce ayrıca açıklanmalıdır.')),
 ('ornek','2. Örnek arama ve gösterimler',paras(
  'Örnek aramada kullanım amacı, işletme türü, bölge ve gösterilecek bilgi alanları seçilir. Sonuçlar temsili kayıtlardan hazırlanır; ilk beş kayıt önizlemede gösterilir. Kalan sonuç sayısı da örnek senaryonun parçasıdır; gerçek pazar büyüklüğü, gerçek arama sonucu veya erişilebilir veri adedi olarak yorumlanmamalıdır.',
  'Hazırlanıyor ekranındaki aşamalar, tanıtım akışını anlatan görsel bir senaryodur. Örnek moddaki bekleme süresi, canlı veri servisinin hızı veya gerçek işletme bilgilerinin o sırada toplandığı anlamına gelmez.',
  'Örneklerdeki işletme adları, telefonlar, alan adları, adresler ve değerlendirme puanları gerçek iletişim veya müşteri referansı olarak kullanılmamalıdır. Görseller ve tasarlanmış site önizlemeleri, gösterilen işletmelerle ticari ilişki veya müşteri ilişkisi bulunduğu anlamına gelmez.')),
 ('kullanim','3. Kullanım sınırları',paras(
  'Siteyi ve örnek dosyaları ürünü değerlendirmek, işleyişi öğrenmek ve kendi çalışma düzeninizi denemek için kullanabilirsiniz. Örnek kayıtların gerçek olmadığını belirten açıklamalar korunmalıdır.',
  'Yetkisiz erişim girişimleri, güvenlik önlemlerini aşma, zararlı kod gönderme, sistemi aksatacak şekilde istek üretme ve üçüncü kişilerin haklarını ihlal edecek kullanım yasaktır. Siteye başkasının şifresini, kimlik bilgisini, ödeme bilgisini veya özel nitelikli kişisel verilerini girmeyin.',
  'İnternette erişilebilir bir bilginin bulunması, o bilginin her amaçla toplanmasına, yeniden yayımlanmasına veya ticari iletişim için kullanılmasına kendiliğinden izin vermez. Gerçek bir veri kaynağıyla çalışılırken ilgili kişilerin hakları, platformun kullanım kuralları ve uygulanabilir mevzuat ayrıca gözetilmelidir.')),
 ('dosyalar','4. Örnek dosyalar ve bilgilerin doğruluğu',paras(
  'İndirilebilir örnek CSV dosyaları temsili kayıtlar içerir. Dosyaları elektronik tablo programınızda açabilir ve deneme amaçlı düzenleyebilirsiniz. Bu dosyalar gerçek müşterilere ulaşılabilecek bir veri tabanı değildir.',
  'Ürün anlatımında belirtilen telefon, web sitesi, adres, konum ve değerlendirme gibi alanlar; gerçek hizmette kullanılması hâlinde kaynak profilde bulunmasına ve güncel olmasına bağlıdır. Eksiksiz kayıt, kesintisiz hizmet, kesin doğruluk, belirli sayıda işletme veya satış sonucu garantisi verilmez.',
  'Bir işletmeyle iletişim kurmadan önce kimliğini, sunduğu hizmeti ve iletişim kanalını doğrulamak; iletişimin amacı ve yöntemi için gereken hukuki şartları değerlendirmek gerekir. Bu site otomatik arama, toplu mesaj veya e-posta kampanyası başlatmaz.')),
 ('ucret','5. Ücret, üyelik ve tüketici hakları',paras(
  'Bu tanıtım sitesi üzerinden kart bilgisi alınmaz ve ücret tahsil edilmez. Bir paketi incelemek, örnek aramayı başlatmak veya iletişim taslağı hazırlamak kendiliğinden ücretli üyelik, otomatik yenileme ya da ödeme yükümlülüğü oluşturmaz.',
  'Ücretli bir uygulama hizmeti sunulduğunda toplam bedel, vergiler, kullanım süresi, hizmet kapsamı, varsa yenileme ve sona erdirme şartları işlemden önce açıkça gösterilmelidir. Gerekli ön bilgilendirme ve ilgili sözleşmeler sunulmadan bu önizleme bir satın alma adımı olarak kullanılmamalıdır.',
  'Tüketici işlemlerine uygulanabilen emredici hükümler ile cayma, iptal, iade, ayıplı hizmet ve başvuru hakları saklıdır. “Dijital hizmet olduğu için hiçbir koşulda iade olmaz” şeklinde genel bir hak kaybı bu koşullarla oluşturulmaz. Ücretli işlemin niteliğine göre uygulanabilecek istisnalar, ancak kanuni şartları varsa ve gerekli bilgilendirme yapılarak değerlendirilir.')),
 ('haklar','6. İçerik ve fikrî haklar',paras(
  'Sitedeki tasarımlar, metinler, özgün çizimler, yazılım unsurları ve marka görselleri ilgili hak sahiplerine aittir. Üçüncü taraf fotoğrafları, harita verileri ve yazılım bileşenleri kendi lisans ve kullanım şartlarına tabidir. Bir içeriğin sitede gösterilmesi, tüm haklarının Veri Burada’ya ait olduğu anlamına gelmez.',
  'Siteyi inceleme ve örnek çıktıyı deneme imkânı; markanın taklit edilmesine, site içeriğinin yanıltıcı biçimde başka bir hizmet gibi sunulmasına veya üçüncü taraf haklarının ihlaline izin vermez. Kanunun tanıdığı kullanım hakları saklıdır.',
  'Google Haritalar ve sitede adı geçen diğer üçüncü taraf hizmetleri, ilgili hak sahiplerinin hizmetleridir. Bu isimlerin ürün anlatımında geçmesi resmî ortaklık, onay veya yetkilendirme beyanı değildir.')),
 ('erisilebilirlik','7. Teknik erişim ve sorumluluk',paras(
  'İnternet bağlantısı, tarayıcı özellikleri, bakım veya teknik arıza nedeniyle önizleme işlevleri geçici olarak çalışmayabilir. Animasyonlar ve örnek senaryolar farklı cihazlarda farklı hızlarda görüntülenebilir.',
  'Site içeriği ürünün işleyişini tanıtır; kişiye özel hukuki, mali veya ticari danışmanlık değildir. Bir araştırma sonucunun nasıl kullanılacağına ilişkin karar yalnızca bir örnek ekran üzerinden verilmemelidir.',
  'Bu koşulların hiçbir hükmü, uygulanabilir emredici mevzuatın öngördüğü sorumluluğu veya tüketici haklarını ortadan kaldıracak şekilde yorumlanamaz. Özellikle kasıt ya da ağır kusurdan doğan sorumluluğun kaldırıldığı anlamına gelmez.')),
 ('baglantilar','8. İletişim ve haricî bağlantılar',paras(
  'Sitedeki iletişim düğmesi, konu ve mesajınızı e-posta uygulamanızda açar. Mesajı gönderme işlemini siz tamamlarsınız; sitede formun doldurulması teslim veya yanıt garantisi oluşturmaz. İletişim için belirtilen adres: <a href="mailto:destek@veriburada.com">destek@veriburada.com</a>.',
  'Haricî bir bağlantıya geçtiğinizde ilgili hizmetin kendi şartları ve gizlilik uygulamaları geçerli olur. Sitedeki her haricî bağlantı için içerik, kullanılabilirlik veya güvenlik garantisi verilmez; kanunen kaldırılamayan sorumluluklar saklıdır.',
  'Veri kullanımı hakkında ayrıntılar <a href="/gizlilik-politikasi/">Gizlilik Politikası</a> sayfasındadır. Siteyi ziyaret etmek veya örnek aramayı denemek, ilgisiz veri işleme faaliyetlerine açık rıza verildiği anlamına gelmez.')),
 ('guncelleme','9. Güncellemeler ve uyuşmazlıklar',paras(
  'Sitenin işlevleri değiştiğinde kullanım koşulları da değişen kapsama göre güncellenebilir. Değişiklikler geçmişte doğmuş hakları kendiliğinden ortadan kaldırmaz; ücretli bir sözleşmenin şartlarını geriye dönük ve tek taraflı değiştirme yetkisi vermez. Son güncelleme tarihi bu sayfanın başında gösterilir.',
  'Türkiye hukukunun uygulanabildiği durumlarda ilgili mevzuat hükümleri geçerlidir. Tüketici sıfatına sahip kişilerin, işlem tutarına ve yürürlükteki kurallara göre tüketici hakem heyetleri, tüketici mahkemeleri ve diğer yetkili mercilere başvuru hakları saklıdır. Bu metin belirli bir şehir mahkemesini herkes için münhasır yetkili kılmaz.',
  'Mesafeli işlemlere ilişkin resmî açıklamalar için <a href="https://tuketici.ticaret.gov.tr/yayinlar/tuketici-bilgi-rehberi/mesafeli-sozlesmeler-hakkinda-bilgilendirme" rel="noopener noreferrer" target="_blank">Ticaret Bakanlığının mesafeli sözleşmeler rehberini</a> inceleyebilirsiniz.'))
]

add('gizlilik-politikasi','Gizlilik Politikası | Veri Burada','Veri Burada tanıtım sitesinde arama tercihleri, tarayıcı depolaması, örnek sonuçlar, iletişim ve kişisel veri hakları hakkında açıklamalar.','Gizlilik Politikası','Veri Burada tanıtım sitesi ve ücretsiz örnek deneyimde hangi bilgilerin, nasıl kullanıldığını öğrenin.',legal_document(privacy,('kullanim-kosullari','Kullanım koşulları')),noindex=True,legal=True)
